import numpy as np
t,x,v,a=df['t'].values,df['x'].values,df['v'].values,df['dv_dt'].values
def poly(y,deg):
    cols=[];nms=[]
    for i in range(deg+1):
        for j in range(deg+1-i):
            cols.append(x**i*v**j); nms.append((i,j))
    A=np.column_stack(cols); c,_,_,_=np.linalg.lstsq(A,y,rcond=None)
    return np.mean((y-A@c)**2)/np.var(y), dict((n,round(k,3)) for n,k in zip(nms,c) if abs(k)>1e-3)
